<?php

namespace Repositories;

use Doctrine\ORM\EntityRepository;

/**
 * Log
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class Log extends EntityRepository
{
	/**
     * Load logs for log list .
     *
     * @param \Entities\Admin $admin Admin for filtering mailboxes.
     * @param \Entities\Domain $domain Domain for filtering mailboxes.
     * @return array
     */
    public function loadForLogList( $admin, $domain = null )
    {
        $qb = $this->getEntityManager()->createQueryBuilder()
            ->select( 'l.id as id , l.action as action, l.data as data, l.timestamp as timestamp, a.username as admin, d.domain as domain' )
            ->from( '\\Entities\\Log', 'l' )
            ->leftJoin( 'l.Domain', 'd' )
            ->join( 'l.Admin', 'a' );
        
        if( $admin )
            $qb->join( 'd.Admins', 'd2a' )
                ->where( 'd2a = ?1' )
                ->setParameter( 1, $admin );

        if( $domain )
            $qb->andWhere( 'l.Domain = ?2' )
                ->setParameter( 2, $domain );

        return $qb->getQuery()->getArrayResult();  
    }

    /**
     * Load the log entries of a single mailbox, newest first.
     *
     * There is no mailbox foreign key on the log table, so entries are matched on
     * the mailbox's address in the message text (the address is unique per domain).
     *
     * @param \Entities\Mailbox $mailbox The mailbox to load the history for.
     * @param int $limit Maximum number of entries to return.
     * @return array
     */
    public function loadForMailbox( $mailbox, $limit = 200 )
    {
        $qb = $this->getEntityManager()->createQueryBuilder()
            ->select( 'l.action as action, l.data as data, l.timestamp as timestamp, a.username as admin' )
            ->from( '\\Entities\\Log', 'l' )
            ->leftJoin( 'l.Admin', 'a' )
            ->where( 'l.data LIKE ?1' )
            ->orderBy( 'l.timestamp', 'DESC' )
            ->setMaxResults( $limit )
            // shortcut: no index on log.data, so this is a scan of the log table, which is
            // fine at current volumes; add a mailbox_id column to log if it ever gets big.
            ->setParameter( 1, '%' . $mailbox->getUsername() . '%' );

        return $qb->getQuery()->getArrayResult();
    }
}
